package org.eclipse.ui.genericeditor.examples.dotproject;

import org.eclipse.jface.text.TextAttribute;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.graphics.RGB;
import org.eclipse.swt.widgets.Display;

public class TestClass {
    public void method() {
        TextAttribute differentColorAttribute = new TextAttribute(new Color(Display.getCurrent(), new RGB(255,0, 0))); // Red, should not match
        Color customColor = new Color(Display.getCurrent(), 10, 20, 30); // Different constructor, should not match
    }
}
